// Modified 2026-10-05: vanilla water only; distant SSR fades to native fallback.
vec4 reflection_calc(vec3 fragpos, vec3 normal, vec3 reflected, inout float infinite, float dither) {
    float ssrWeight = shaderlodWaterSSRWeight(fragpos);
    // Skip before ANY trace/depth/scene fetch. Native sky/cloud color remains
    // in water_shader; infinite=1 retains the native offscreen sun glint path.
    if (ssrWeight <= 0.0) {
        infinite = 1.0;
        return vec4(0.0);
    }

    vec3 pos = shaderlodWaterRaymarch(reflected, fragpos, infinite, dither);
    float border =
        clamp((1.0 - (max(0.0, abs(pos.y - 0.5)) * 2.0)) * 50.0, 0.0, 1.0);
    border = clamp(border - pow(pos.y, 10.0), 0.0, 1.0);
    pos.x = abs(pos.x);
    if (pos.x > 1.0) {
        pos.x = 1.0 - (pos.x - 1.0);
    }
    // Pinned gaux1 is unmipmapped. Explicit base-level sample makes the new
    // nonuniform distance branch independent of implicit texture derivatives.
    return vec4(texture2DLod(gaux1, pos.xy, 0.0).rgb, border * ssrWeight);
}

